class IRValidatorException(Exception):
    """Raised when mandatory data is missing in spec file."""
    pass

class SpecValidator:
    REQUIRED_FIELDS = {"name", "version", "spec"}

    @classmethod
    def validate_from_content(cls, spec_content=None):
        """
        validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
            is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("No spec content supplied")

        try:
            data = yaml.load(spec_content, Loader=SafeLoader)
        except Exception as exc:
            raise IRValidatorException(f"Failed to parse YAML: {exc}")

        if not isinstance(data, dict):
            raise IRValidatorException("Spec YAML must be a mapping at top level")

        missing = cls.REQUIRED_FIELDS - data.keys()
        if missing:
            raise IRValidatorException(f"Missing required fields: {', '.join(sorted(missing))}")

        return data

